def backfill_measurement_timestamps(apps, schema_editor):
    """Preserve the old recorded timestamp and Jalali measurement date."""
    timezone = django.utils.timezone
    for model_name in ("BodyCircumferenceMeasurement", "CaliperMeasurement"):
        model = apps.get_model("account", model_name)
        for record in model.objects.all().iterator():
            measured_at = record.recorded_at
            raw_jalali = (record.measured_at_jalali or "").strip()
            parts = raw_jalali.replace("-", "/").split("/")
            if len(parts) == 3:
                try:
                    year, month, day = (int(part) for part in parts)
                    if 1300 <= year <= 1600:
                        gregorian = jdatetime.date(year, month, day).togregorian()
                        measured_at = timezone.make_aware(
                            datetime.combine(gregorian, time(12, 0)),
                            timezone.get_default_timezone(),
                        )
                except (TypeError, ValueError):
                    pass
            model.objects.filter(pk=record.pk).update(measured_at=measured_at)


